export type SteeringCompletionStatus =
  | "pending"
  | "suspended"
  | "in_progress"
  | "delivered"
  | "discarded"
  | "failed";

export interface SteeringCompletionItem {
  id: string;
  requesterSessionKey: string;
  status: SteeringCompletionStatus;
  result?: unknown;
  prompt?: string;
  steeringLeaseId?: string;
  steeringLeaseAt?: number;
  acknowledgedAt?: number;
  releasedAt?: number;
  canceledAt?: number;
}

export interface SteeringLease {
  leaseId: string;
  steeringLeaseId: string;
  requesterSessionKey: string;
  itemIds: string[];
  prompt: string;
  createdAt: number;
}

export interface SteeringLeaseOptions {
  requesterSessionKey: string;
  limit?: number;
  now?: number;
  leaseId?: string;
  staleAfterMs?: number;
}

export interface SteeringAckOptions {
  leaseId?: string;
  steeringLeaseId?: string;
  now?: number;
}

export interface SteeringReleaseOptions {
  leaseId?: string;
  steeringLeaseId?: string;
  now?: number;
}

const DEFAULT_STALE_AFTER_MS = 5 * 60 * 1000;
const TERMINAL_STATUSES = new Set<SteeringCompletionStatus>([
  "delivered",
  "discarded",
  "failed",
]);

function asRecord(value: unknown): Record<string, unknown> {
  return value !== null && typeof value === "object"
    ? (value as Record<string, unknown>)
    : {};
}

function resultText(result: unknown): string {
  if (result === undefined || result === null) return "";
  if (typeof result === "string") return result;
  try {
    return JSON.stringify(result);
  } catch {
    return String(result);
  }
}

function mergePrompt(items: SteeringCompletionItem[]): string {
  const sections = items.map((item) => {
    const explicit = item.prompt?.trim();
    if (explicit) return explicit;
    const record = asRecord(item.result);
    const prompt = record.prompt;
    if (typeof prompt === "string" && prompt.trim()) return prompt.trim();
    const rendered = resultText(item.result);
    return rendered ? `Steering completion ${item.id}: ${rendered}` : `Steering completion ${item.id}`;
  });
  return sections.join("\n\n");
}

/**
 * In-process, requester-isolated queue for steering completions.
 *
 * A lease is the sole authority to acknowledge a completion. Releasing a lease
 * atomically returns its items to pending, while acknowledging it atomically
 * makes them delivered. A stale in-progress lease can be reclaimed after a
 * restart (or after the owning turn has disappeared).
 */
export class AgentSteeringQueue {
  private readonly items = new Map<string, SteeringCompletionItem>();
  private readonly leases = new Map<string, SteeringLease>();

  constructor(
    private readonly clock: () => number = () => Date.now(),
    private readonly staleAfterMs: number = DEFAULT_STALE_AFTER_MS,
  ) {}

  enqueue(
    item: SteeringCompletionItem & { requesterSessionKey: string },
  ): SteeringCompletionItem {
    const copy: SteeringCompletionItem = {
      ...item,
      status: item.status ?? "pending",
    };
    this.items.set(copy.id, copy);
    return { ...copy };
  }

  complete(
    id: string,
    result: unknown,
    requesterSessionKey: string,
    prompt?: string,
  ): SteeringCompletionItem {
    const item: SteeringCompletionItem = {
      id,
      requesterSessionKey,
      status: "pending",
      result,
      ...(prompt === undefined ? {} : { prompt }),
    };
    this.items.set(id, item);
    return { ...item };
  }

  cancel(id: string, now: number = this.clock()): boolean {
    const item = this.items.get(id);
    if (!item || TERMINAL_STATUSES.has(item.status) || item.status === "in_progress") {
      return false;
    }
    item.status = "discarded";
    item.canceledAt = now;
    delete item.steeringLeaseId;
    delete item.steeringLeaseAt;
    return true;
  }

  terminate(id: string, status: "delivered" | "discarded" | "failed" = "failed", now: number = this.clock()): boolean {
    const item = this.items.get(id);
    if (!item || TERMINAL_STATUSES.has(item.status)) return false;
    item.status = status;
    item.canceledAt = now;
    delete item.steeringLeaseId;
    delete item.steeringLeaseAt;
    return true;
  }

  listPending(requesterSessionKey: string): SteeringCompletionItem[] {
    return [...this.items.values()]
      .filter(
        (item) =>
          item.requesterSessionKey === requesterSessionKey &&
          (item.status === "pending" || item.status === "suspended"),
      )
      .map((item) => ({ ...item }));
  }

  lease(options: SteeringLeaseOptions): SteeringLease | null {
    const now = options.now ?? this.clock();
    const requesterSessionKey = options.requesterSessionKey;
    const limit = Math.max(0, options.limit ?? 1);
    if (limit === 0) return null;

    const candidates = [...this.items.values()]
      .filter((item) => item.requesterSessionKey === requesterSessionKey)
      .filter((item) => {
        if (item.status === "pending" || item.status === "suspended") return true;
        return (
          item.status === "in_progress" &&
          item.steeringLeaseId !== undefined &&
          now - (item.steeringLeaseAt ?? 0) > (options.staleAfterMs ?? this.staleAfterMs)
        );
      })
      .sort((a, b) => (a.steeringLeaseAt ?? 0) - (b.steeringLeaseAt ?? 0));

    const selected = candidates.slice(0, limit);
    if (selected.length === 0) return null;
    const leaseId = options.leaseId ?? `steering-lease-${now}-${this.nextSequence()}`;
    const leased: SteeringLease = {
      leaseId,
      steeringLeaseId: leaseId,
      requesterSessionKey,
      itemIds: selected.map((item) => item.id),
      prompt: "",
      createdAt: now,
    };
    leased.prompt = mergePrompt(selected);

    for (const item of selected) {
      item.status = "in_progress";
      item.steeringLeaseId = leaseId;
      item.steeringLeaseAt = now;
      delete item.acknowledgedAt;
      delete item.releasedAt;
    }
    this.leases.set(leaseId, leased);
    return { ...leased, itemIds: [...leased.itemIds] };
  }

  acknowledge(options: SteeringAckOptions): boolean {
    const leaseId = options.steeringLeaseId ?? options.leaseId;
    if (!leaseId) return false;
    const lease = this.leases.get(leaseId);
    if (!lease) return false;
    const now = options.now ?? this.clock();
    let changed = false;
    for (const item of this.items.values()) {
      if (item.steeringLeaseId !== leaseId) continue;
      if (item.status !== "in_progress") continue;
      item.status = "delivered";
      item.acknowledgedAt = now;
      changed = true;
    }
    if (changed) this.leases.delete(leaseId);
    return changed;
  }

  release(options: SteeringReleaseOptions): boolean {
    const leaseId = options.steeringLeaseId ?? options.leaseId;
    if (!leaseId) return false;
    const lease = this.leases.get(leaseId);
    if (!lease) return false;
    const now = options.now ?? this.clock();
    let changed = false;
    for (const item of this.items.values()) {
      if (item.steeringLeaseId !== leaseId || item.status !== "in_progress") continue;
      item.status = "pending";
      item.releasedAt = now;
      delete item.steeringLeaseId;
      delete item.steeringLeaseAt;
      changed = true;
    }
    this.leases.delete(leaseId);
    return changed;
  }

  getItem(id: string): SteeringCompletionItem | undefined {
    const item = this.items.get(id);
    return item ? { ...item } : undefined;
  }

  private nextSequence(): number {
    return this.leases.size + 1;
  }
}

export function createAgentSteeringQueue(
  clock: () => number = () => Date.now(),
  staleAfterMs: number = DEFAULT_STALE_AFTER_MS,
): AgentSteeringQueue {
  return new AgentSteeringQueue(clock, staleAfterMs);
}

export const agentSteeringQueue = createAgentSteeringQueue();

export default AgentSteeringQueue;

